ee:message.ee:set-payload:
%dw 2.0
output application/json

// Variables de control
var statusCode = vars.vRespuesta.status default 200
var responseBody = vars.vRespuesta

// Booleano para saber si el cliente realmente vino en el body
var hasCustomer = responseBody.GetPartnerViewResponse != null
---
{
  "code": statusCode as String,

  "message": if (hasCustomer) "Subscriber retrieved successfully" 
             else responseBody.error,

  "data": if (hasCustomer) do {
      // Usamos 'do' para crear variables locales solo si hay éxito
      var customer = responseBody.GetPartnerViewResponse.GetPartnerViewResult.Customer
      var individual = customer.IndividualRole
      ---
      {
        "id": customer.ID,
        "serviceSpecification": {
          "name": "OTT"
        },
        "state": {
          "id": customer.status.id,
          "name": customer.status.name
        },
        "customer": [
          {
            "id": customer.ID,
            "name": individual.NameUsing.IndividualNames.formattedName,
            "givenNames": individual.NameUsing.IndividualNames.givenNames,
            "familyNames": individual.NameUsing.IndividualNames.familyNames,
            "middleNames": individual.NameUsing.IndividualNames.middleNames default "",
            "aristocraticTitle": individual.NameUsing.IndividualNames.aristocraticTitle default "",
            "aliveDuring": {
              "startDateTime": individual.aliveDuring.startDateTime
            },
            "identifiedBy": individual.IdentifiedBy.IndividualIdentifications filter ($.cardNr != null) map (id) -> {
              "scan": id.scan,
              "cardNr": id.cardNr
            },
            "contactMedium": customer.ContactableVia.ContactMedium map (contact) -> {
              "eMailAddress": contact.eMailAddress default "",
              "addressId": contact.AddressId,
              "eMailProtocol": contact.eMailProtocol default "Email"
            },
            "address": customer.AddressList.UrbanPropertyAddress map (addr) -> {
              "addressCode": addr.addressCode default "",
              "city": addr.city,
              "streetNrFirst": addr.streetNrFirst,
              "locality": addr.locality,
              "streetName": addr.streetName,
              "postCode": addr.postCode
            }
          }
        ],
        "serviceCharacteristic": [
          {
            "name": "customerInquiryList",
            "value": responseBody.GetPartnerViewResponse.GetPartnerViewResult.CustomerInquiryList.CustomerInquiry default []
          },
          {
            "name": "customerProductList",
            // AQUÍ ESTABA EL ERROR: Filtramos para que solo pasen Objetos
            "value": (responseBody.GetPartnerViewResponse.GetPartnerViewResult.CustomerProductList.Product default []) 
                     filter ($ is Object) map (prod) -> {
              "productStatus": prod.productStatus,
              "productCategory": prod.productCategory
            }
          }
        ]
      }
  } else {} // Si no existe el cliente, data queda como objeto vacío
}
